CREATE TABLE "PortfolioProfile" ("id" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "headline" TEXT NOT NULL DEFAULT '', "about" TEXT NOT NULL DEFAULT '', "specialization" TEXT NOT NULL DEFAULT '', "skills" TEXT NOT NULL DEFAULT '[]', "links" TEXT NOT NULL DEFAULT '[]', "featuredPostIds" TEXT NOT NULL DEFAULT '[]', "accent" TEXT NOT NULL DEFAULT 'violet', "layout" TEXT NOT NULL DEFAULT 'grid', "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PortfolioProfile_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PortfolioProfile_ownerId_key" ON "PortfolioProfile"("ownerId");
ALTER TABLE "PortfolioProfile" ADD CONSTRAINT "PortfolioProfile_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "CreativeProject" ("id" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "coverUrl" TEXT, "role" TEXT NOT NULL DEFAULT '', "collaborators" TEXT NOT NULL DEFAULT '', "link" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CreativeProject_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CreativeProject_ownerId_createdAt_idx" ON "CreativeProject"("ownerId", "createdAt");
ALTER TABLE "CreativeProject" ADD CONSTRAINT "CreativeProject_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;